CREATE TABLE reserve_account(id uuid PRIMARY KEY,version bigint NOT NULL,club_id uuid NOT NULL UNIQUE REFERENCES club(id),custodian_id uuid NOT NULL REFERENCES app_user(id),bank_name varchar(100) NOT NULL,last4 varchar(4) NOT NULL,holder_name varchar(100) NOT NULL,account_cipher text NOT NULL,verification_reference varchar(255) NOT NULL,balance bigint NOT NULL CHECK(balance BETWEEN 0 AND 9007199254740991));
CREATE TABLE reserve_entry(id uuid PRIMARY KEY,version bigint NOT NULL,account_id uuid NOT NULL REFERENCES reserve_account(id),event_id uuid REFERENCES club_event(id),created_by uuid NOT NULL REFERENCES app_user(id),sent_by uuid REFERENCES app_user(id),confirmed_by uuid REFERENCES app_user(id),recipient_id uuid REFERENCES app_user(id),kind varchar(20) NOT NULL CHECK(kind IN ('DEPOSIT','SPEND','DISSOLUTION','REVERSAL')),status varchar(30) NOT NULL CHECK(status IN ('PROPOSED','TRANSFER_PENDING','CONFIRMED','REQUESTED','COMPLETED','CANCELLED')),amount bigint NOT NULL CHECK(amount BETWEEN 1 AND 9007199254740991),purpose varchar(255) NOT NULL,sent_reference varchar(255),confirmed_reference varchar(255),actual_record_reason varchar(1000),actual_recorded_by uuid REFERENCES app_user(id),unbacked_at_actual_record bigint NOT NULL DEFAULT 0 CHECK(unbacked_at_actual_record BETWEEN 0 AND 9007199254740991),actual_recorded_at timestamptz,created_at timestamptz NOT NULL,sent_at timestamptz,actual_at timestamptz,UNIQUE(confirmed_by,confirmed_reference));
CREATE INDEX reserve_entry_event ON reserve_entry(event_id);
CREATE TABLE responsibility_handover(id uuid PRIMARY KEY,version bigint NOT NULL,event_id uuid REFERENCES club_event(id),account_id uuid REFERENCES reserve_account(id),proposer_id uuid NOT NULL REFERENCES app_user(id),candidate_id uuid NOT NULL REFERENCES app_user(id),inventory_amount bigint NOT NULL CHECK(inventory_amount BETWEEN 0 AND 9007199254740991),inventory_note varchar(1000) NOT NULL,inventory_snapshot text,snapshot_version bigint NOT NULL,requires_reacceptance boolean NOT NULL DEFAULT false,status varchar(30) NOT NULL CHECK(status IN ('PROPOSED','ACCEPTED','FUNDS_PENDING','COMPLETED','DECLINED','CANCELLED','RECEIVED_STALE','SUPERSEDED','RETURNED')),sent_reference varchar(255),received_reference varchar(255),created_at timestamptz NOT NULL,sent_at timestamptz,received_at timestamptz,CHECK((event_id IS NOT NULL)<>(account_id IS NOT NULL)),CHECK(proposer_id<>candidate_id));
CREATE TABLE club_owner_transfer(id uuid PRIMARY KEY,version bigint NOT NULL,club_id uuid NOT NULL REFERENCES club(id),proposer_id uuid NOT NULL REFERENCES app_user(id),candidate_id uuid NOT NULL REFERENCES app_user(id),status varchar(20) NOT NULL CHECK(status IN ('PROPOSED','COMPLETED')),created_at timestamptz NOT NULL,CHECK(proposer_id<>candidate_id));

CREATE TABLE advance_repayment(id uuid PRIMARY KEY,version bigint NOT NULL,event_id uuid NOT NULL REFERENCES club_event(id),creditor_id uuid NOT NULL REFERENCES app_user(id),payer_id uuid REFERENCES app_user(id),created_by uuid NOT NULL REFERENCES app_user(id),amount bigint NOT NULL CHECK(amount BETWEEN 1 AND 9007199254740991),status varchar(20) NOT NULL CHECK(status IN ('REQUESTED','SENT','CONFIRMED','CANCELLED')),reason varchar(1000) NOT NULL,sent_reference varchar(200),received_reference varchar(200),created_at timestamptz NOT NULL,sent_at timestamptz,confirmed_at timestamptz,UNIQUE(creditor_id,received_reference),CHECK(created_by<>creditor_id OR status<>'REQUESTED'));
CREATE INDEX advance_repayment_event ON advance_repayment(event_id);
CREATE TABLE advance_recovery(id uuid PRIMARY KEY,version bigint NOT NULL,event_id uuid NOT NULL REFERENCES club_event(id),actor_id uuid NOT NULL REFERENCES app_user(id),amount bigint NOT NULL CHECK(amount BETWEEN 1 AND 9007199254740991),kind varchar(20) NOT NULL CHECK(kind='SELF_RECOVERY'),reason varchar(1000) NOT NULL,created_at timestamptz NOT NULL);
CREATE INDEX advance_recovery_event ON advance_recovery(event_id);

CREATE TABLE handover_return(id uuid PRIMARY KEY,version bigint NOT NULL,handover_id uuid REFERENCES responsibility_handover(id),event_id uuid NOT NULL REFERENCES club_event(id),sender_id uuid NOT NULL REFERENCES app_user(id),recipient_id uuid NOT NULL REFERENCES app_user(id),amount bigint NOT NULL CHECK(amount BETWEEN 1 AND 9007199254740991),kind varchar(30) NOT NULL DEFAULT 'HANDOVER_RETURN' CHECK(kind IN ('HANDOVER_RETURN','CUSTODY_TRANSFER')),status varchar(20) NOT NULL CHECK(status IN ('REQUESTED','SENT','CONFIRMED','CANCELLED')),reason varchar(1000) NOT NULL,sent_reference varchar(200),received_reference varchar(200),created_at timestamptz NOT NULL,sent_at timestamptz,received_at timestamptz,UNIQUE(recipient_id,received_reference),CHECK(sender_id<>recipient_id));
CREATE INDEX handover_return_event ON handover_return(event_id);
